package com.alsafa.native4.core;

import android.content.ContentValues;import android.database.sqlite.SQLiteDatabase;import org.json.JSONArray;import org.json.JSONObject;import java.util.List;import java.util.UUID;
/** Writes all payment legs for one source inside caller transaction. */
public final class SplitPaymentStore {
 private SplitPaymentStore(){}
 public static JSONArray write(SQLiteDatabase db,String sourceType,String sourceId,List<Payment> payments,long now)throws Exception{if(payments==null||payments.isEmpty())throw new IllegalArgumentException("أضف دفعة واحدة على الأقل");JSONArray json=new JSONArray();for(Payment p:payments){if(p==null||!Double.isFinite(p.amount)||p.amount<=0)throw new IllegalArgumentException("مبلغ الدفعة غير صالح");String cur=MoneyRules.currency(p.currency),method=req(p.paymentMethod,"طريقة الدفع").toUpperCase(),account=req(p.account,"الخزنة").toUpperCase();MoneyRules.requireSupported(account,cur);MoneyRules.requirePaymentSupported(method,cur);if("LATER".equals(method))throw new IllegalArgumentException("المبلغ الآجل ليس دفعة مقبوضة");String id="payment-"+UUID.randomUUID();ContentValues v=new ContentValues();v.put("payment_id",id);v.put("source_type",sourceType);v.put("source_id",sourceId);v.put("amount",p.amount);v.put("currency",cur);v.put("payment_method",method);v.put("account",account);v.put("created_at",now);db.insertOrThrow("payment_splits",null,v);ContentValues c=new ContentValues();c.put("move_id","cash-"+UUID.randomUUID());c.put("source_type",sourceType);c.put("source_id",sourceId);c.put("direction","IN");c.put("amount",p.amount);c.put("currency",cur);c.put("payment_method",method);c.put("drawer",account);c.put("created_at",now);db.insertOrThrow("cash_moves",null,c);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,sourceType+"_PAYMENT",id,cur,p.amount,now);json.put(new JSONObject().put("paymentId",id).put("amount",p.amount).put("currency",cur).put("paymentMethod",method).put("account",account).put("usdPerUnit",fx.usdPerUnit).put("usdAmount",fx.usdAmount));}return json;}
 public static final class Payment{public final double amount;public final String currency,paymentMethod,account;public Payment(double amount,String currency,String paymentMethod,String account){this.amount=amount;this.currency=currency;this.paymentMethod=paymentMethod;this.account=account;}}
 private static String req(String v,String l){String s=v==null?"":v.trim();if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}
}
